      const ancestors = collectAncestors(container, root);
      // 文字行移到容器上方(overflow:hidden裁切)，子容器隐藏
      container.children.forEach(c => {
        if (c.id?.startsWith('expanded-')) c.opacity = 0;
        else if (c.id?.startsWith('title-') || c.id?.startsWith('file-')) c.transform.translateY = -fullHeight;
      });
      renderer?.setRoot(renderer!.getRoot()!);
      // 容器高度动画 + 文字滑下动画同步开始
      const textRows = container.children.filter(c =>
        c.id?.startsWith('title-') || c.id?.startsWith('file-')
