外层代码看起来对。问题是子容器展开时，它的文字没有动画。让我看 `slideInRows` 里子容器展开后的处理：
<tool_GuEi name="package_proxy">
  <param name="tool_name">linux_ssh:linux_ssh_exec</param>
  <param name="params">{&quot;command&quot;: &quot;sed -n &apos;660,710p&apos; /root/kfmv4/src/client/modules/tree-render.ts&quot;}</param>
</tool_GuEi><tool_result_I0PW name="linux_ssh:linux_ssh_exec" status="success"><content>{"packageVersion":"0.1.0","success":true,"timeoutMs":10000,"exitCode":0,"timedOut":false,"output":"/**

/**
 * SlideInRows: 收集容器内直接子行，��部上移隐藏��再逐行用 translateY 滑下。
 * 盒子链串行展开子容器，每个子容器展开后递归调用自身。
 */
function slideInRows(container: Box, root: Box, selfToggle?: any): void {
  const rows = container.children.filter(c =>
    (c.id?.startsWith('title-') || c.id?.startsWith('file-'))
  );
  if (rows.length === 0) return;

  const totalH = container.height;
  const containerOrigYs = (container as any)._origYs as number[] | undefined;
  if (containerOrigYs && container.children.length === containerOrigYs.length) {
    container.children.forEach((c, j) => { c.y = containerOrigYs[j]; });
  }
  // 恢复子容器可见
  container.children.forEach(c => {
    if (c.id?.startsWith('expanded-')) c.opacity = 1;
  });
  renderer?.setRoot(renderer!.getRoot()!);

  // ====== 盒子链：串行展开子容器，一个完再展开下一个 ======
  const subContainers = container.children.filter(
    c => c.id?.startsWith('expanded-') && (c as any)._fullHeight > 0
  );
  function expandNext(idx: number): void {
    if (idx >= subContainers.length) return;
    const child = subContainers[idx];
    const subFullH = (child as any)._fullHeight;
    child.children.forEach(c => {
      if (c.id?.startsWith('expanded-')) c.opacity = 0;
    });
    const tog = (child as any)._toggleBox;
    if (tog) tog.transform.rotate = 0;
    gsap.to(child, {
      height: subFullH,
      duration: 0.05,
      ease: 'power2.out',
      onUpdate: () => { renderer?.setRoot(renderer!.getRoot()!); },
      onComplete: () => {
        expandNext(idx + 1);
        slideInRows(child, root, tog);
      },
    });
  }
  expandNext(0);

  // ====== 当前容器 toggle 旋转（和文字链并行） ======","sessionId":"","error":""}</content></tool_result_I0PW>

