  <param name="params">{&quot;command&quot;: &quot;cat &gt; /tmp/fix_slide2.js &lt;&lt; &apos;ENDSCRIPT&apos;
const fs = require(&apos;fs&apos;);
let code = fs.readFileSync(&apos;/root/kfmv4/src/client/modules/tree-render.ts&apos;, &apos;utf8&apos;);

// 修改1: 删掉 slideInRows 底部的逐行文字动画
const old1 = `  // ====== 文字链：已在外层（容器展开时）同步播放 ======
  rows.forEach((row, i) =&gt; {
    const rowDelay = (i * 25) / 1000;
    gsap.to(row.transform, {
      translateY: 0,
      duration: 0.2,
      ease: &apos;power2.out&apos;,
      delay: rowDelay,
      onUpdate: () =&gt; { renderer?.setRoot(renderer!.getRoot()!); },
    });
  });`;
const new1 = `  // 文字滑入动画已在外层同步播放`;
if (code.includes(old1)) { code = code.replace(old1, new1); console.log(&apos;Done 1&apos;); }
else { console.log(&apos;Pattern 1 not found&apos;); }

// 修改2: 子容器展开时，文字行移到上方 + 同步滑下动画
const old2 = `    child.children.forEach(c =&gt; {
      if (c.id?.startsWith(&apos;expanded-&apos;)) c.opacity = 0;
    });
    const tog = (child as any)._toggleBox;
    if (tog) tog.transform.rotate = 0;
    gsap.to(child, {
      height: subFullH,
      duration: 0.05,
      ease: &apos;power2.out&apos;,
      onUpdate: () =&gt; { renderer?.setRoot(renderer!.getRoot()!); },
      onComplete: () =&gt; {
        expandNext(idx + 1);
        slideInRows(child, root, tog);
      },
    });`;

const new2 = `    child.children.forEach(c =&gt; {
      if (c.id?.startsWith(&apos;expanded-&apos;)) c.opacity = 0;
      else if (c.id?.startsWith(&apos;title-&apos;) || c.id?.startsWith(&apos;file-&apos;)) c.transform.translateY = -subFullH;
    });
    const tog = (child as any)._toggleBox;
    if (tog) tog.transform.rotate = 0;
    // 子容器高度动画 + 文字滑下同步
    const childTextRows = child.children.filter(c =&gt;
      c.id?.startsWith(&apos;title-&apos;) || c.id?.startsWith(&apos;file-&apos;)
    );
    childTextRows.forEach(r =&gt; {
      gsap.to(r.transform, {
        translateY: 0,
        duration: 0.25,
        ease: &apos;power2.out&apos;,
        onUpdate: () =&gt; { renderer?.setRoot(renderer!.getRoot()!); },
      });
    });
    gsap.to(child, {
      height: subFullH,
      duration: 0.05,
      ease: &apos;power2.out&apos;,
      onUpdate: () =&gt; { renderer?.setRoot(renderer!.getRoot()!); },
      onComplete: () =&gt; {
        expandNext(idx + 1);
        slideInRows(child, root, tog);
      },
    });`;
if (code.includes(old2)) { code = code.replace(old2, new2); console.log(&apos;Done 2&apos;); }
else { console.log(&apos;Pattern 2 not found&apos;); }

fs.writeFileSync(&apos;/root/kfmv4/src/client/modules/tree-render.ts&apos;, code);
ENDSCRIPT
node /tmp/fix_slide2.js&quot;}</param>
